import com.comsol.model.*;import com.comsol.model.util.*;
public class ReactiveSolveLowMach{
 static Model m;static String prefix;static int seq=0;
 static void solve(double v)throws Exception{m.param().set("V_cell",v+"[V]");m.param().set("alpha_rxn","1");m.sol("sol1").feature("s1").feature("p1").set("plist",new String[][]{{Double.toString(v)}});System.out.println("SOLVE_START|V="+v+"|alpha=1|lowMach");System.out.flush();m.sol("sol1").runAll();m.save(prefix+"_latest.mph");System.out.println("SOLVE_SAVED|V="+v);System.out.flush();String tag="lowMachWarm"+seq++;m.sol("sol1").copySolution(tag);m.sol("sol1").feature("v1").set("initsol",tag);m.sol("sol1").feature("v1").set("solnum","1");}
 public static void main(String[] a){try{ModelUtil.initStandalone(false);ModelUtil.showPlots(false);ModelUtil.showProgress(a[2]);m=ModelUtil.load("LowMachDiagnostic",a[0]);prefix=a[1];m.physics("fp").feature().remove("massFaraday");m.physics("fp").prop("PhysicalModelProperty").set("Compressibility","CompressibleMALT03");m.component("comp1").multiphysics().create("rxnflow","ReactingFlow");m.component("comp1").multiphysics("rxnflow").set("Fluid_physics","fp");m.component("comp1").multiphysics("rxnflow").set("Species_physics","tcs");m.sol("sol1").copySolution("lowMachInitial");m.sol("sol1").feature("v1").set("initsol","lowMachInitial");m.sol("sol1").feature("v1").set("solnum","1");m.sol("sol1").feature("s1").feature("fc1").set("initstep","0.1");m.sol("sol1").feature("s1").feature("fc1").set("maxiter","100");m.save(prefix+"_configured.mph");for(int k=0;k<=5;k++){solve((80-k)/100.);if(k==0)m.save(prefix+"_S5.mph");if(k==5)m.save(prefix+"_S6.mph");}System.exit(0);}catch(Throwable e){System.out.println("LOW_MACH_SOLVE_FAILED");e.printStackTrace(System.out);System.exit(1);}}
}
